// ============================================
// FUNÇÕES AUXILIARES
// ============================================

function buscarLocalPorReferencia(referencia) {
  const refNorm = referencia.replace('🔮 ', '').trim();
  for (const key in locaisBiblicos) {
    const refs = (locaisBiblicos[key].referencias || []).map(r => r.replace('🔮 ', '').trim());
    if (refs.includes(refNorm)) return locaisBiblicos[key];
  }
  return null;
}

function buscarLocalPorIdLocal(idLocal) {
  return locaisBiblicos[idLocal] || null;
}

function buscarLocaisPorPeriodo(periodoId) {
  const resultados = [];
  for (const key in locaisBiblicos) {
    if (locaisBiblicos[key].periodoId === periodoId) resultados.push(locaisBiblicos[key]);
  }
  return resultados;
}

function buscarLocaisPorEvento(eventoId) {
  const resultados = [];
  for (const key in locaisBiblicos) {
    if (locaisBiblicos[key].eventoId === eventoId) resultados.push(locaisBiblicos[key]);
  }
  return resultados;
}

function buscarLocaisPorTipo(tipo) {
  const resultados = [];
  for (const key in locaisBiblicos) {
    if (locaisBiblicos[key].tipo === tipo) resultados.push(locaisBiblicos[key]);
  }
  return resultados;
}

function buscarLocalPorNomeOriginal(nomeOriginal) {
  for (const key in locaisBiblicos) {
    if (locaisBiblicos[key].nomeOriginal === nomeOriginal) return locaisBiblicos[key];
  }
  return null;
}

// ============================================
// EXPORTAÇÃO
// ============================================

if (typeof window !== "undefined") {
  window.locaisBiblicos = locaisBiblicos;
  window.buscarLocalPorReferencia = buscarLocalPorReferencia;
  window.buscarLocalPorIdLocal = buscarLocalPorIdLocal;
  window.buscarLocaisPorPeriodo = buscarLocaisPorPeriodo;
  window.buscarLocaisPorEvento = buscarLocaisPorEvento;
  window.buscarLocaisPorTipo = buscarLocaisPorTipo;
  window.buscarLocalPorNomeOriginal = buscarLocalPorNomeOriginal;
}

if (typeof module !== "undefined") {
  module.exports = {
    locaisBiblicos,
    buscarLocalPorReferencia,
    buscarLocalPorIdLocal,
    buscarLocaisPorPeriodo,
    buscarLocaisPorEvento,
    buscarLocaisPorTipo,
    buscarLocalPorNomeOriginal
  };
}

console.log("✅ locais-biblicos.js (v3.1) carregado!");
console.log("📊 Total de locais: " + Object.keys(locaisBiblicos).length);
